INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3938998f-4355-4ad3-8919-f8f47caa1afe', 'Incremento de Renta', '5', '5', 'AJUSTE DE LA RENTA', E'- The monthly rent will increase every year starting from the date the premises are delivered.\n- The increase will occur on each anniversary of this date throughout the lease term.\n- The rent increase will match the percentage increase of the National Consumer Price Index (INPC).\n- The INPC is published by the National Institute of Statistics and Geography in the Official Gazette.\n- The increase is based on the INPC for the 12 months immediately before the rent increase date.', 'Las Partes convienen que la Renta Mensual será incrementada anualmente contado a partir de la fecha de entrega del local y así subsecuentemente cada aniversario de la fecha durante toda la vigencia del arrendamiento, en el mismo porcentaje de incremento del Índice Nacional de Precios al Consumidor (INPC) que publique el Intitulo Nacional de Estadística y Geografía en el Diario Oficial de la Federación para el periodo de 12 (doce) meses inmediato anterior a la fecha en que deba incrementarse la renta mensual');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3938998f-4355-4ad3-8919-f8f47caa1afe', 'Late Fees', '13', '17', 'INTERESES MORATORIOS', E'- The Tenant must make all payments on time as agreed in the contract.\n- If the Tenant is late with any payment, they will have to pay late interest.\n- The late interest is 10% per month on the overdue amount.\n- This interest applies for each month or part of a month the payment is late.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue:\n\nLa falta del pago oportuno de la renta estipulada dentro del plazo señalado, dará derecho a la Arrendadora a cobrar intereses moratorios a razón del 10% (diez por ciento) mensual adicional de su importe por el simple retraso, por cada mes o fracción en que incurra en mora.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('a95e8b51-79e5-4438-8d8f-3b4cf4b7ce38', 'La Paz Puebla', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '1901 Avenida 9 Poniente', 'SN-2', 'Puebla', 'Puebla', '72410', 'MX', '1901 Avenida 9 Poniente, SN-2, Puebla, Puebla 72410', 19.048183, -98.213862, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'Puebla La Paz', 1890, 1890, NULL, '{"map_lease_expiration_date":"2027-05-08","map_marker_color":"#A879D2","coordinate":"rooftop|19.0481830000|-98.2138620000|accurate","city_state":"Puebla, Puebla","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Ejército Nacional 769, Torre B, Piso 15, Granada, Miguel Hidalgo, Ciudad De México 11520","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2032-05-08","lease_expiration_date":"2027-05-08","lease_length_in_months_remaining":7,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57978,"grid_name":"La Paz Puebla","grid_full_address":"1901 Avenida 9 Poniente, SN-2, Puebla, Puebla 72410","map_addr_1":"1901 Avenida 9 Poniente","map_addr_2":"SN-2","map_city_state_zip":"Puebla, Puebla 72410","grid_brand":"Planet Fitness","location_created_at":"2025-10-06 14:34:56","active_lease_count_over_time":51328,"location_count_over_time":57978,"remaining_rent_liability_over_time":51328}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('e39719c4-dc99-4491-8392-2d8daaae2fe6', 'a95e8b51-79e5-4438-8d8f-3b4cf4b7ce38', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'La Paz Puebla Lease: PUMEX, S.A. De C.V. (05/09/2022 - 05/08/2027)', NULL, false, 'activo', 'Lease', NULL, '2022-12-01', '2022-05-09', '2027-05-08', '2037-05-08', false, 2, NULL, 2, NULL, NULL, NULL, NULL, 59, 'PUMEX, S.A. De C.V. > Controinmuebles, S.A. de C.V.', NULL, NULL, 'Ejército Nacional 769', 'Torre B, Piso 15', 'Granada, Miguel Hidalgo', 'Ciudad De México', '11520', 'MX', NULL, NULL, NULL, 120, 'percent', NULL, NULL, 623700, 'La Arrendataria se obliga a entregar a la Arrendadora, a la fecha de firma del presente contrato, $623,700.00 M.N. (seiscientos veintitrés mil setecientos pesos 00/100 moneda nacional), más el correspondiente Impuesto al Valor Agregado. Dicha cantidad se recibirá en calidad de depósito y será aplicada a los últimos 3 (tres) meses del arrendamiento del primer año, contado a partir de la fecha en que la Arrendataria tiene la obligación de abrir las puertas al público de la negociación que operará en el Local Comercial de la fecha en que efectivamente abra sus puertas al público, lo que ocurra primero. Esta cantidad se entregará a la Arrendadora en su domicilio o en cualquiera de las modalidades estipuladas en la Cláusula Segunda del presente instrumento.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"renewal_notice_period_start_original":"120 Days Prior"}'::jsonb);
