INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e39719c4-dc99-4491-8392-2d8daaae2fe6', 'Common Area Maintenance Charges', '10', '10 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord an additional 10% of the Monthly Rent plus VAT for administration and maintenance costs.\n- This payment is calculated based on the current rent amount at the time the payment is due.\n- The Tenant cannot request an account of how these funds are used or influence the management or maintenance decisions of the Shopping Center.\n- The Landlord is required to use these funds to maintain, repair, and replace parts of the Shopping Center to keep it in good working condition.', 'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 10% (diez por ciento), del importe de la Renta Mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e39719c4-dc99-4491-8392-2d8daaae2fe6', 'Incremento de Renta', '7', '5', 'AJUSTE DE LA RENTA', E'- The monthly rent will increase every year starting from the date the premises are delivered.\n- The increase will be based on the percentage change in the National Consumer Price Index (INPC) over the previous 12 months.\n- The maximum increase is capped at 7% unless both parties agree in writing to a different amount.', 'Las Partes convienen que la Renta Mensual será incrementada anualmente, contado a partir de la fecha de entrega del local y así subsecuentemente cada aniversario de la fecha  durante toda la vigencia del arrendamiento, en el mismo porcentaje de incremento del Índice Nacional de Precios al Consumidor (INPC) que publique el Intitulo Nacional de Estadística y Geografía en el Diario Oficial de la Federación para el periodo de 12 (doce) meses inmediato anterior a la fecha en que deba incrementarse la renta mensual. Las Partes acuerdan que el incremento nunca podrá exceder del 7% (siete por ciento) para la Arrendataria, a menos que Las Partes acuerden por escrito algo distinto.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e39719c4-dc99-4491-8392-2d8daaae2fe6', 'Late Fees', '14', '17', 'INTERESES MORATORIOS', E'- The Tenant must make all payments on time as agreed in the contract.\n- If the Tenant is late with any payment, they will have to pay late fees.\n- The late fee is an additional 10% per month on the overdue amount for each month or part of a month the payment is late.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue:\n\nLa falta del pago oportuno de la renta estipulada dentro del plazo señalado, dará derecho a la Arrendadora a cobrar intereses moratorios a razón del 10% (diez por ciento) mensual adicional de su importe por el simple retraso, por cada mes o fracción en que incurra en mora.');
