INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3d7a795c-c10e-474f-aac4-7c0e86bec734', 'Late Fees', '5', '3', 'RENTA E INCREMENTOS', E'- If the Tenant does not pay the Rent and the applicable VAT on time as agreed in the contract, they must pay the Landlord interest.\n- The interest is calculated at a rate of 7% per month plus the applicable VAT.\n- Interest is charged from the date the payment is late until the date the full amount is paid.', E'Para el caso de que el Arrendatario no cubra puntualmente la Renta y el IV.A. respectivo en la forma estipulada en el presente contrato, se obliga a pagarle al Arrendador los Intereses que habrán de ser calculados a la Tasa de Interés establecida en el Capitulo de Definiciones, más el I.V.A. correspondiente, a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente haya pagado el importe de tales conceptos.\n\nInterés o, al plural, Intereses: Los intereses calculados a la Tasa del 7% (Siete por ciento) mensual más el I.V.A. correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3d7a795c-c10e-474f-aac4-7c0e86bec734', 'Incremento de Renta', '6', '3.8', 'RENTA E INCREMENTOS', E'- The monthly rent will increase every 12 months starting from the Rent Payment Start Date.\n- The first increase occurs 12 months after the Rent Payment Start Date.\n- The increase is based on inflation during that period but cannot exceed 6%.\n- This process repeats every 12 months.\n- Inflation is determined by comparing the Consumer Price Index (CPI) from the month before the 12-month period starts to the CPI at the end of that period.\n- The percentage increase is applied to the current rent, and the new amount becomes the rent for the next 12 months, plus applicable VAT.', 'Las "Partes" convienen en que el monto de la Renta mensual convenida en el inciso 3.1 de esta cláusula será incrementado cada 12 (doce) meses a partir de la Fecha de Inicio de Pago de Renta. El primer incremento se hará una vez transcurridos 12 (doce) meses contados a partir de la Fecha de Inicio de Pago de Renta, de conformidad con la Inflación del mismo período, no pudiendo ser en ningún caso mayor al 6% (seis por ciento). El mismo procedimiento se repetirá cada doce meses a partir de la Fecha de Inicio de Pago de Renta. Para la determinación de la Inflación del periodo de que se trate, se comparará el Indice Nacional de Precios al Consumidor del mes inmediato anterior al del inicio del período de doce meses, con el Índice del último mes de dicho periodo. El incremento porcentual resultante de estos 12 (doce) meses se aplicará al importe de la Renta vigente; el resultado se sumará a la última Renta y la cantidad que así resulte será el importe de la Renta mensual para los siguientes 12 (doce) meses, más el I.V.A. correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3d7a795c-c10e-474f-aac4-7c0e86bec734', 'Common Area Maintenance Charges', '11', '13.2 a)', 'CUOTAS DE MANTENIMIENTO Y OTROS CONCEPTOS A CARGO DEL ARRENDATARIO', E'- El inquilino debe pagar $58,080.00 MXN mensualmente.\n- Esta cantidad aumentará según lo indicado en el contrato.\n- Se debe agregar el IVA y otros impuestos aplicables.\n- El pago comienza desde la fecha de inicio del alquiler.\n- Se paga por adelantado dentro de los primeros 10 días naturales de cada mes.\n- El arrendador enviará la factura por correo electrónico dentro de los primeros 5 días hábiles de cada mes.\n- Si el pago no se realiza a tiempo, se generarán intereses más IVA desde el momento del retraso hasta que se pague.', E'El "Arrendatario" deberá pagar por el concepto previsto en el presente inciso, la cantidad mensual de $58,080.00 M.N. (Cincuenta y ocho mil pesos 00/100 Moneda Nacional) misma cantidad que se incrementará conforme al mecanismo de incremento previsto en el numeral 3.8. de la Cláusula Tercera del presente Contrato. Una vez determinado el monto de la cuota deberá adicionarse a la cantidad correspondiente el I.V.A. aplicable o cualquier otro impuesto, derecho o aprovechamiento que dispongan las leyes fiscales Mexicanas Federales, Locales, vigentes. \n\nLa obligación de pago de esta suma a cargo del "Arrendatario", surgirá a partir de la Fecha de Inicio de Pago de la Renta y se pagará por mes adelantado dentro de los primeros 10 (diez) dias naturales de cada mes, por lo que dentro de los primeros 5 (cinco) días hábiles de cada mes el "Arrendador" emitirá y enviara al "Arrendatario" la factura correspondiente a través de correo electrónico con dirección fpt arrendamiento@fpt.com.mx, la falta puntual de su pago generarȧ intereses más el IVA correspondiente, que habrán de ser calculados a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente haya pagado el importe de tales conceptos.');
